/**
 * Build a YouTube *search* URL from a keyword.
 *
 * Security (Mejora 1 del plan): we NEVER render URLs generated by the LLM. The
 * LLM only ever produces search keywords; the client turns them into safe
 * search links here.
 */
export function youtubeSearchUrl(keyword: string): string {
  return `https://www.youtube.com/results?search_query=${encodeURIComponent(keyword)}`;
}
